arguments.command:
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# Function URL rejects query keys outside A-Za-z0-9_.- (EVT-412)
for f in event seat refund; do
  bash bin/render "$f" | grep -o 'action="[^"]*"' | while read -r l; do
    u=${l#action=\"}; u=${u%\"}; q=${u#*\?}; k=${q%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "illegal query key in $u"; exit 1; }
  done || fail=1
done
exit $fail
EOF
bash tests/forms_test.sh
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must stay within A-Za-z0-9_.- : the Function URL rejects other keys (e.g. SvelteKit's ?/name) with 400.
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
EOF
bash tests/forms_test.sh; echo rc=$?; bash scripts/verify.sh; echo rc=$?

